import{_ as a,c as i,o as t,a2 as r}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/installation.md","filePath":"fr/guide/installation.md","lastUpdated":1793163976000}'),s={name:"fr/guide/installation.md"};function o(n,e,l,p,u,c){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>NueZip est disponible pour macOS via le Mac App Store.</p><h2 id="options-de-telechargement" tabindex="-1">Options de téléchargement <a class="header-anchor" href="#options-de-telechargement" aria-label="Permalink to &quot;Options de téléchargement&quot;">​</a></h2><h3 id="mac-app-store-recommande" tabindex="-1">Mac App Store (recommandé) <a class="header-anchor" href="#mac-app-store-recommande" aria-label="Permalink to &quot;Mac App Store (recommandé)&quot;">​</a></h3><ul><li><strong>Téléchargement</strong> : <a href="https://apps.apple.com/app/id6785846417" target="_blank" rel="noreferrer">NueZip sur le Mac App Store</a></li></ul><p>La version du Mac App Store propose des mises à jour automatiques et une intégration transparente avec macOS.</p><h3 id="versions-github-alternative" tabindex="-1">Versions GitHub (alternative) <a class="header-anchor" href="#versions-github-alternative" aria-label="Permalink to &quot;Versions GitHub (alternative)&quot;">​</a></h3><p>Si vous préférez télécharger directement, vous pouvez obtenir l&#39;application depuis <a href="https://github.com/nuezip/nuezip/releases" target="_blank" rel="noreferrer">GitHub Releases</a>. Notez que cette version ne reçoit pas de mises à jour automatiques.</p><h2 id="etapes-d-installation" tabindex="-1">Étapes d&#39;installation <a class="header-anchor" href="#etapes-d-installation" aria-label="Permalink to &quot;Étapes d&#39;installation&quot;">​</a></h2><h3 id="mac-app-store" tabindex="-1">Mac App Store <a class="header-anchor" href="#mac-app-store" aria-label="Permalink to &quot;Mac App Store&quot;">​</a></h3><ol><li>Cliquez sur le lien de téléchargement ci-dessus ou recherchez « NueZip » dans le Mac App Store</li><li>Cliquez sur « Obtenir » pour télécharger l&#39;application</li><li>L&#39;application se téléchargera et s&#39;installera automatiquement</li><li>Lancez NueZip depuis votre dossier Applications ou Launchpad</li></ol><h3 id="versions-github" tabindex="-1">Versions GitHub <a class="header-anchor" href="#versions-github" aria-label="Permalink to &quot;Versions GitHub&quot;">​</a></h3><ol><li>Téléchargez le dernier <code>.dmg</code> depuis la page des Releases</li><li>Double-cliquez sur le <code>.dmg</code> téléchargé pour l&#39;ouvrir</li><li>Glissez l&#39;icône <code>NueZip.app</code> dans votre dossier <code>Applications</code></li><li>Éjectez l&#39;image montée et ouvrez <code>NueZip</code> depuis <code>Applications</code></li></ol><p>Si macOS empêche l&#39;ouverture de l&#39;application (Gatekeeper), ouvrez <strong>Réglages système → Confidentialité et sécurité</strong> et cliquez sur <strong>Ouvrir quand même</strong> pour NueZip, ou faites un clic droit sur l&#39;application et choisissez <strong>Ouvrir</strong>.</p><h2 id="premier-lancement" tabindex="-1">Premier lancement <a class="header-anchor" href="#premier-lancement" aria-label="Permalink to &quot;Premier lancement&quot;">​</a></h2><p>Lors du premier lancement de NueZip, vous serez guidé à travers un parcours de prise en main pour :</p><ul><li><strong>Accorder l&#39;accès aux dossiers</strong> : Autorisez NueZip à accéder aux répertoires courants (Téléchargements, Documents, Bureau)</li><li><strong>Activer l&#39;extension Finder</strong> : Activez le menu contextuel au clic droit pour des opérations d&#39;archives rapides</li></ul><p>Accordez les permissions lorsque cela vous est demandé. Vous pouvez les modifier à tout moment dans <strong>Réglages système → Confidentialité et sécurité</strong>.</p><h2 id="mises-a-jour" tabindex="-1">Mises à jour <a class="header-anchor" href="#mises-a-jour" aria-label="Permalink to &quot;Mises à jour&quot;">​</a></h2><ul><li><strong>Version Mac App Store</strong> : Les mises à jour sont gérées automatiquement par l&#39;App Store</li><li><strong>Version GitHub Releases</strong> : Téléchargez la version plus récente et remplacez l&#39;application dans <code>Applications</code></li></ul><h2 id="desinstallation" tabindex="-1">Désinstallation <a class="header-anchor" href="#desinstallation" aria-label="Permalink to &quot;Désinstallation&quot;">​</a></h2><p>Pour désinstaller NueZip :</p><ol><li>Quittez NueZip</li><li>Glissez <code>NueZip.app</code> de <code>Applications</code> vers la Corbeille</li><li>(Facultatif) Supprimez les données et journaux de l&#39;application :</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Logs/nuezip</span></span></code></pre></div><h2 id="configuration-requise" tabindex="-1">Configuration requise <a class="header-anchor" href="#configuration-requise" aria-label="Permalink to &quot;Configuration requise&quot;">​</a></h2><ul><li><strong>macOS</strong> : Sonoma (14) ou ultérieur recommandé</li><li><strong>Processeur</strong> : Apple Silicon (série M) ou Intel (64 bits)</li><li><strong>Mémoire</strong> : 4 Go minimum, 8 Go recommandé</li><li><strong>Stockage</strong> : ~50 Mo</li></ul><h2 id="depannage" tabindex="-1">Dépannage <a class="header-anchor" href="#depannage" aria-label="Permalink to &quot;Dépannage&quot;">​</a></h2><p>Si vous rencontrez des problèmes lors de l&#39;installation :</p><ul><li><strong>macOS bloque l&#39;application</strong> : Ouvrez <strong>Réglages système → Confidentialité et sécurité</strong> et cliquez sur <strong>Ouvrir quand même</strong> pour NueZip</li><li><strong>Avertissement de notarisation</strong> : Téléchargez une version signée/notariée depuis le Mac App Store</li></ul><p>Pour plus d&#39;aide, consultez le <a href="./troubleshooting.html">guide de dépannage</a>.</p>`,30)])])}const m=a(s,[["render",o]]);export{h as __pageData,m as default};
